package org.springframework.samples.petclinic.rest.validation;

/**
 * Thrown when an owner is created with a normalized telephone number that is
 * already used by another owner. Handled by the REST
 * {@code ExceptionControllerAdvice}, which translates it into a
 * {@code 409 Conflict} response.
 */
public class DuplicateTelephoneException extends RuntimeException {

    public DuplicateTelephoneException(String message) {
        super(message);
    }
}

